function TabContentPractice({ content }) {
	return (
		<div>
			<h1>Tab Content</h1>;
			{content.map((item) => (
				<>
					<h4>{item.summary}</h4>
					<p>{item.details}</p>
				</>
			))}
		</div>
	);
}

export default TabContentPractice;
